assets/theme.css:
/* Cove — EcomStrait Liquid theme. Editorial: wide margins, serif headings,
   a 3-up product grid and colour used only as punctuation. */
*,*::before,*::after{box-sizing:border-box}
html{-webkit-text-size-adjust:100%}
body{margin:0;font-family:var(--font-body);color:var(--ink);background:var(--bg);line-height:1.7;-webkit-font-smoothing:antialiased}
img{max-width:100%;height:auto;display:block;object-fit:cover}
a{color:inherit;text-decoration:none}
h1,h2,h3{font-family:var(--font-heading);line-height:1.2;margin:0;font-weight:400}
.muted{color:var(--muted)}
.container{width:100%;max-width:1140px;margin:0 auto;padding:0 28px}
.section{padding:96px 0}
.section--narrow{max-width:660px;margin:0 auto}
.section-title{font-size:clamp(1.8rem,3.4vw,2.7rem);letter-spacing:-.015em}
.section-head{display:flex;align-items:flex-end;justify-content:space-between;gap:24px;margin-bottom:44px}
.eyebrow{margin:0 0 10px;font-size:.7rem;font-weight:700;text-transform:uppercase;letter-spacing:.2em;color:var(--brand)}
.link-more{font-size:.88rem;color:var(--muted);border-bottom:1px solid var(--line);padding-bottom:3px;white-space:nowrap;transition:color .2s ease,border-color .2s ease}
.link-more:hover{color:var(--ink);border-color:var(--ink)}

/* Buttons — understated, outlined by default */
.btn{display:inline-flex;align-items:center;justify-content:center;gap:.5rem;border:1px solid var(--ink);cursor:pointer;font-family:var(--font-body);font-weight:600;font-size:.86rem;padding:.8rem 1.5rem;border-radius:var(--radius);transition:background-color .25s ease,color .25s ease,border-color .25s ease}
.btn-lg{padding:.95rem 1.9rem;font-size:.92rem}
.btn-primary{background:var(--ink);color:var(--bg)}
.btn-primary:hover{background:transparent;color:var(--ink)}
.btn-primary[disabled]{background:transparent;color:var(--muted);border-color:var(--line);cursor:not-allowed}
.btn-ghost{background:transparent;border-color:var(--line);color:var(--muted)}
.btn-ghost:hover{border-color:var(--ink);color:var(--ink)}

/* Header */
.site-header{position:sticky;top:0;z-index:20;background:color-mix(in srgb,var(--bg) 90%,transparent);backdrop-filter:blur(10px);border-bottom:1px solid var(--line)}
.site-header__inner{display:flex;align-items:center;justify-content:space-between;gap:28px;height:80px}
.site-header__name{font-family:var(--font-heading);font-size:1.4rem;letter-spacing:-.01em}
.site-nav{display:flex;gap:28px}
.site-nav__link{font-size:.88rem;color:var(--muted);padding-bottom:2px;border-bottom:1px solid transparent;transition:color .2s ease,border-color .2s ease}
.site-nav__link:hover,.site-nav__link.is-active{color:var(--ink);border-color:var(--brand)}
.site-header__cart{font-size:.88rem;display:inline-flex;align-items:center;gap:8px}
.cart-count{display:inline-grid;place-items:center;min-width:21px;height:21px;padding:0 6px;border-radius:999px;background:var(--brand);color:var(--bg);font-size:.72rem;font-weight:700}
@media (max-width:640px){.site-nav{display:none}.site-header__inner{height:64px}}

/* Hero — left-aligned, editorial measure */
.hero{background:var(--wash);background-size:cover;background-position:center;border-bottom:1px solid var(--line)}
.hero__inner{padding:112px 28px;max-width:900px;margin:0;text-align:left}
.hero__heading{font-size:clamp(2.2rem,5.6vw,4rem);letter-spacing:-.02em;max-width:18ch}
.hero__subheading{font-size:clamp(1rem,1.7vw,1.2rem);color:var(--muted);margin:24px 0 36px;max-width:48ch}
.hero--image .hero__inner{padding:152px 28px}
@media (max-width:640px){.hero__inner,.hero--image .hero__inner{padding:72px 24px}}

/* Grids — 3-up products for larger editorial imagery */
.grid{display:grid;gap:36px 28px}
.grid-products{grid-template-columns:repeat(2,1fr)}
.grid-collections{grid-template-columns:repeat(2,1fr)}
.grid-3{grid-template-columns:repeat(3,1fr)}
@media (min-width:720px){.grid-products{grid-template-columns:repeat(3,1fr)}.grid-collections{grid-template-columns:repeat(3,1fr)}}
@media (max-width:640px){.grid-3{grid-template-columns:1fr;gap:28px}}

/* Product card — caption-style, portrait imagery */
.product-card{display:flex;flex-direction:column;overflow:hidden;background:transparent}
.product-card__media{position:relative;aspect-ratio:4/5;overflow:hidden;background:var(--wash)}
.product-card__media img{width:100%;height:100%;transition:opacity .3s ease}
.product-card:hover .product-card__media img{opacity:.86}
.product-card__placeholder,.product-card--placeholder{aspect-ratio:4/5;background:linear-gradient(150deg,var(--wash),color-mix(in srgb,var(--accent) 8%,var(--bg)))}
.product-card__body{padding:16px 0 0;display:flex;flex-direction:column;gap:4px}
.product-card__title{font-family:var(--font-heading);font-size:1.05rem;line-height:1.35}
.product-card__price{font-size:.86rem;color:var(--muted)}
.badge{position:absolute;top:14px;left:14px;padding:4px 11px;border-radius:var(--radius);font-size:.68rem;font-weight:700;text-transform:uppercase;letter-spacing:.12em}
.badge--soldout{background:var(--bg);color:var(--ink);border:1px solid var(--line)}
.price--sale .price__was{color:var(--muted);margin-right:8px}
.price--sale .price__now{color:var(--ink);font-weight:600}

/* Product page */
.product{display:grid;grid-template-columns:1fr 1fr;gap:72px;align-items:start}
@media (max-width:820px){.product{grid-template-columns:1fr;gap:36px}}
.product__title{font-size:clamp(1.9rem,3.2vw,2.7rem);letter-spacing:-.015em}
.product__price{font-size:1.15rem;color:var(--muted);margin:14px 0 32px;padding-bottom:32px;border-bottom:1px solid var(--line)}
.product__options{display:flex;flex-wrap:wrap;gap:20px;margin-bottom:28px}
.product__option{display:flex;flex-direction:column;gap:8px;font-size:.7rem;font-weight:700;text-transform:uppercase;letter-spacing:.16em;color:var(--muted)}
.product__option select{padding:.65rem .85rem;background:var(--bg);border:1px solid var(--line);border-radius:var(--radius);color:var(--ink);font-family:var(--font-body);font-size:.92rem;font-weight:400;letter-spacing:0;text-transform:none}
.product__option select:focus-visible{outline:1px solid var(--brand);outline-offset:1px}
.product__description{margin-top:40px;padding-top:32px;border-top:1px solid var(--line);max-width:56ch;color:var(--muted)}
.product__media-placeholder{aspect-ratio:4/5;background:linear-gradient(150deg,var(--wash),color-mix(in srgb,var(--accent) 8%,var(--bg)))}

/* Value props — numbered editorial list */
.value-props{border-top:1px solid var(--line)}
.value-prop{padding-top:22px;border-top:2px solid var(--ink)}
.value-prop__num{display:block;font-family:var(--font-heading);font-size:.82rem;color:var(--brand);margin-bottom:14px;letter-spacing:.1em}
.value-prop__title{font-size:1.15rem;margin-bottom:8px}

/* Cart */
.cart-line{display:grid;grid-template-columns:80px 1fr auto auto;gap:22px;align-items:center;padding:22px 0;border-bottom:1px solid var(--line)}
.cart-line__title{font-family:var(--font-heading);font-size:1.02rem}
.cart-line__qty{width:66px;padding:.55rem;background:var(--bg);border:1px solid var(--line);border-radius:var(--radius);text-align:center;color:var(--ink);font-family:var(--font-body)}
.cart-footer{display:flex;flex-wrap:wrap;justify-content:space-between;gap:20px;align-items:center;padding-top:28px}
.cart-subtotal{display:flex;align-items:baseline;gap:14px;font-size:.72rem;text-transform:uppercase;letter-spacing:.16em;color:var(--muted)}
.cart-subtotal strong{font-family:var(--font-heading);font-size:1.6rem;font-weight:400;letter-spacing:0;color:var(--ink);text-transform:none}
.cart-actions{display:flex;gap:14px}

/* Collections */
.collection-card{position:relative;display:block;overflow:hidden;background:var(--wash)}
.collection-card img{transition:opacity .3s ease}
.collection-card:hover img{opacity:.86}
.collection-card__title{position:absolute;left:16px;bottom:16px;background:var(--bg);padding:8px 16px;border-radius:var(--radius);font-family:var(--font-heading);font-size:.98rem}
.collection-head{margin-bottom:44px;padding-bottom:24px;border-bottom:1px solid var(--line)}
.collection-head__desc{max-width:56ch;margin-top:12px}

/* Misc */
.rte{max-width:62ch}
.rte a{color:var(--ink);text-decoration:underline;text-decoration-color:var(--brand);text-underline-offset:4px}
.pagination{display:flex;gap:20px;justify-content:center;margin-top:56px;font-size:.88rem;color:var(--muted)}
.pagination a:hover{color:var(--ink)}
.pagination .is-current{color:var(--ink);border-bottom:1px solid var(--brand)}
.search-form{display:flex;gap:14px;margin:24px 0 40px;max-width:560px}
.search-form input{flex:1;padding:.8rem 1rem;background:var(--bg);border:1px solid var(--line);border-radius:var(--radius);color:var(--ink);font-family:var(--font-body)}
.search-form input::placeholder{color:var(--muted)}
.search-form input:focus-visible{outline:1px solid var(--brand);outline-offset:1px}
:focus-visible{outline:1px solid var(--brand);outline-offset:2px}

/* Footer */
.site-footer{margin-top:72px;border-top:1px solid var(--line);padding:64px 0 32px}
.site-footer__inner{display:flex;flex-wrap:wrap;justify-content:space-between;gap:36px}
.site-footer__name{font-family:var(--font-heading);font-size:1.25rem;margin:0 0 8px}
.site-footer__nav{display:flex;flex-direction:column;gap:12px;font-size:.88rem;color:var(--muted)}
.site-footer__nav a:hover{color:var(--ink)}
.site-footer__legal{margin-top:48px;padding-top:24px;border-top:1px solid var(--line);font-size:.8rem}

@media (prefers-reduced-motion:reduce){*{animation:none!important;transition:none!important}}

